var files = /* @__PURE__ */ new Map();
var binaryFiles = /* @__PURE__ */ new Map();
var dirs = /* @__PURE__ */ new Set();
var mockApp = {
  vault: {
    getMarkdownFiles: () => [...files.keys()].map((p) => ({ path: p })),
    read: async (f4) => files.get(f4.path) || "",
    adapter: {
      exists: async (p) => dirs.has(p) || files.has(p) || binaryFiles.has(p),
      mkdir: async (p) => {
        dirs.add(p);
      },
      write: async (p, c) => {
        files.set(p, c);
      },
      writeBinary: async (p, b) => {
        const view = new Uint8Array(b);
        binaryFiles.set(p, view.buffer.slice(view.byteOffset, view.byteOffset + view.byteLength));
      },
      read: async (p) => files.get(p) || "",
      readBinary: async (p) => binaryFiles.get(p) || new ArrayBuffer(0),
      remove: async (p) => {
        files.delete(p);
        binaryFiles.delete(p);
      },
      list: async (p) => {
        const allKeys = [...files.keys(), ...binaryFiles.keys()];
        const directFiles = allKeys.filter((k) => {
          if (!k.startsWith(p + "/"))
            return false;
          const rest = k.slice(p.length + 1);
          return !rest.includes("/");
        });
        const subFolders = [...dirs].filter((d) => {
          if (!d.startsWith(p + "/"))
            return false;
          const rest = d.slice(p.length + 1);
          return rest.length > 0 && !rest.includes("/");
        });
        return {
          files: directFiles,
          folders: subFolders
        };
      }
    }
  }
};
var mockPlugin = {
  settings: {
    apiKeys: { gemini: "test-key", openai: "", anthropic: "" },
    agents: {
      coordinator: { provider: "gemini", model: "gemini-2.5-flash" },
      professor: { provider: "gemini", model: "gemini-2.5-flash" },
      librarian: { provider: "gemini", model: "gemini-2.5-flash" },
      researcher: { provider: "gemini", model: "gemini-2.5-flash" },
      notetaker: { provider: "gemini", model: "gemini-2.5-flash" }
    }
  }
};
(async () => {
  const engine = new DyResearchEngine(mockApp, mockPlugin);
  engine.initialize();
  const session = await engine.ensureSession("test_session_1");
  import_node_assert.default.strictEqual(session.id, "test_session_1");
  import_node_assert.default.ok(dirs.has("DyResearch") && dirs.has("DyResearch/Sessions"));
  import_node_assert.default.ok(files.has("DyResearch/Sessions/test_session_1.md"));
  await engine.renameSession("test_session_1", "renamed_session");
  import_node_assert.default.ok(files.has("DyResearch/Sessions/renamed_session.md"));
  import_node_assert.default.ok(!files.has("DyResearch/Sessions/test_session_1.md"));
  const listed = await engine.getSessions();
  import_node_assert.default.strictEqual(listed.sessions.length, 1);
  import_node_assert.default.strictEqual(listed.sessions[0].id, "renamed_session");
  console.log("All session markdown checks passed.");
  const minPdf = Buffer.from(
    "%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n3 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R/Contents 4 0 R/Resources<</Font<</F1<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>>>>>>>endobj\n4 0 obj<</Length 58>>stream\nBT /F1 12 Tf 100 700 Td (Scaled Dot-Product Attention Formula) Tj ET\nendstream\nendobj\nxref\n0 5\n0000000000 65535 f \n0000000009 00000 n \n0000000052 00000 n \n0000000101 00000 n \n0000000248 00000 n \ntrailer<</Size 5/Root 1 0 R>>\nstartxref\n356\n%%EOF",
    "utf-8"
  );
  const pdfArrayBuf = minPdf.buffer.slice(minPdf.byteOffset, minPdf.byteOffset + minPdf.byteLength);
  const saved = await saveAndIndexDocument(mockApp, {
    buffer: pdfArrayBuf,
    filename: "Attention_Is_All_You_Need.pdf",
    title: "Attention Is All You Need",
    authors: "Vaswani et al.",
    sourceUrl: "https://arxiv.org/pdf/1706.03762.pdf"
  });
  import_node_assert.default.strictEqual(saved.filePath, "DyResearch/Library/Attention_Is_All_You_Need.pdf");
  import_node_assert.default.strictEqual(saved.indexPath, "DyResearch/Library Index/Attention_Is_All_You_Need.md");
  import_node_assert.default.ok(binaryFiles.has("DyResearch/Library/Attention_Is_All_You_Need.pdf"));
  import_node_assert.default.ok(files.has("DyResearch/Library Index/Attention_Is_All_You_Need.md"));
  import_node_assert.default.ok(!files.get("DyResearch/Library Index/Attention_Is_All_You_Need.md").includes("## Extracted Full Text"));
  const libTools = getLibrarianTools(mockApp);
  const organizeTool = libTools.find((t2) => t2.name === "organize_and_index_document");
  await organizeTool.execute({
    title: "Attention Is All You Need",
    topic_folder: "Machine Learning",
    subject: "machine learning",
    author: "Ashish Vaswani et al.",
    tags: ["transformers", "attention"],
    abstract: "We propose a new simple network architecture, the Transformer.",
    section_titles: ["1 Introduction", "2 Background", "3 Model Architecture"],
    summary: "Introduces the Transformer architecture based solely on attention mechanisms.",
    conclusions: "The Transformer achieves state-of-the-art translation performance."
  });
  import_node_assert.default.ok(binaryFiles.has("DyResearch/Library/Machine Learning/Attention_Is_All_You_Need.pdf"));
  import_node_assert.default.ok(!binaryFiles.has("DyResearch/Library/Attention_Is_All_You_Need.pdf"));
  const updatedIndexMd = files.get("DyResearch/Library Index/Attention_Is_All_You_Need.md");
  import_node_assert.default.ok(updatedIndexMd.includes("Introduces the Transformer architecture"));
  import_node_assert.default.ok(updatedIndexMd.includes("## Abstract"));
  import_node_assert.default.ok(updatedIndexMd.includes("## Section Titles"));
  import_node_assert.default.ok(updatedIndexMd.includes("## Conclusions"));
  import_node_assert.default.ok(!updatedIndexMd.includes("## Extracted Full Text"));
  const profTools = getTeachingTools(mockApp);
  const searchKbTool = profTools.find((t2) => t2.name === "search_knowledge_base");
  const searchRes = await searchKbTool.execute({
    query: "Transformer",
    subject_filter: "machine learning"
  });
  import_node_assert.default.ok(searchRes.includes("Attention_Is_All_You_Need.md"));
  const readLibTool = profTools.find((t2) => t2.name === "read_library_document");
  const readRes = await readLibTool.execute({
    path_or_title: "Attention Is All You Need",
    section_query: "Scaled Dot-Product"
  });
  import_node_assert.default.ok(readRes.includes("Scaled Dot-Product Attention Formula"));
  const catalog = await listLibraryCatalog(mockApp);
  import_node_assert.default.strictEqual(catalog.length, 1);
  import_node_assert.default.strictEqual(catalog[0].topicFolder, "Machine Learning");
  console.log("All PDF download, Library organization, and Library Index reading checks passed!");
})();
